            transport_distances = [float(value) for value in motion_step["crust_transport_distance_km_by_cell"]]
            age_changes = [float(value) for value in motion_step["crust_age_change_ma_by_cell"]]
            thickness_changes = [float(value) for value in motion_step["crust_thickness_change_km_by_cell"]]
            density_changes = [float(value) for value in motion_step["crust_density_change_by_cell"]]
