    groundwater_lateral_sum_km3 = 0.0
    groundwater_recharge_sum_km3 = 0.0
    groundwater_gradient_sum = 0.0
    groundwater_discharge_sum_mm = 0.0
    spring_sum = 0.0
    baseflow_sum = 0.0
