    def _graph_component_count(node_ids: set[int], adjacency: dict[int, set[int]]) -> int:
        remaining = set(node_ids)
        count = 0
        while remaining:
            count += 1
            stack = [remaining.pop()]
            while stack:
                current = stack.pop()
                for neighbor in adjacency.get(current, set()):
                    if neighbor in remaining:
                        remaining.remove(neighbor)
                        stack.append(neighbor)
        return count

    def _validate_graph_record(graph_name: str, expected_node_count: int) -> dict[str, Any]:
        graph = payload.get(graph_name, {})
        if not isinstance(graph, dict):
            failures.append(f"{graph_name} missing or invalid")
            return {"nodes": [], "edges": []}
        nodes = graph.get("nodes", [])
        edges = graph.get("edges", [])
        if not isinstance(nodes, list) or not isinstance(edges, list):
            failures.append(f"{graph_name} nodes or edges invalid")
            return {"nodes": [], "edges": []}
        if int(graph.get("node_count", -1)) != len(nodes) or int(graph.get("edge_count", -1)) != len(edges):
            failures.append(f"{graph_name} count fields do not match records")
        if int(summary.get(f"{graph_name}_node_count", -1)) != expected_node_count:
            failures.append(f"{graph_name}_node_count does not match source records")
        if int(summary.get(f"{graph_name}_edge_count", -1)) != len(edges):
            failures.append(f"{graph_name}_edge_count does not match graph edges")
        return graph

    plates_for_graph = payload.get("plates", [])
