    if int(summary.get("plate_graph_boundary_cell_edge_count", -1)) != plate_boundary_cell_edge_count:
        failures.append("plate_graph_boundary_cell_edge_count does not match cell adjacency edges")
    if int(summary.get("plate_graph_component_count", -1)) != _graph_component_count(plate_ids_for_graph, plate_graph_adjacency):
        failures.append("plate_graph_component_count does not match graph connectivity")

    river_cells_for_graph = {cell_id for cell_id, cell in cells_by_id.items() if bool(cell.get("is_river", False))}
    river_graph = _validate_graph_record("river_graph", len(river_cells_for_graph))
    river_graph_edges = river_graph.get("edges", []) if isinstance(river_graph, dict) else []
    river_graph_adjacency: dict[int, set[int]] = {}
    expected_river_edges: set[tuple[int, int]] = set()
    for cell_id in river_cells_for_graph:
        target = int(cells_by_id[cell_id].get("flow_to", -1))
        target_cell = cells_by_id.get(target)
