        watershed_a = watershed_id_by_basin.get(int(cell_a.get("basin_id", -1)), -1)
        watershed_b = watershed_id_by_basin.get(int(cell_b.get("basin_id", -1)), -1)
        if watershed_a >= 0 and watershed_b >= 0 and watershed_a != watershed_b:
            watershed_pairs.add((min(watershed_a, watershed_b), max(watershed_a, watershed_b)))
